"""仅独立验证服务可持有的任务/版本/证据绑定权限；actor 字符串不是授权。"""

import json
from collections.abc import Iterator
from contextlib import contextmanager
from contextvars import ContextVar
from typing import Protocol
from uuid import UUID

from sqlalchemy.ext.asyncio import AsyncSession

from app.ledger.models import AuditEventType
from app.ledger.service import LedgerService
from app.tasks.models import AITask
from app.tasks.states import VerificationRequired
from app.verifier.models import VerificationReport

_permit: ContextVar[tuple[UUID, int, UUID] | None] = ContextVar("verification_permit", default=None)


class VerificationOutcome(Protocol):
    @property
    def passed(self) -> bool: ...


@contextmanager
def _verification_scope(task_id: UUID, version: int, evidence_id: UUID) -> Iterator[None]:
    token = _permit.set((task_id, version, evidence_id))
    try:
        yield
    finally:
        _permit.reset(token)


async def require_verification(session: AsyncSession, task: AITask) -> None:
    permit = _permit.get()
    if permit is None or permit[:2] != (task.id, task.status_version):
        raise VerificationRequired("RESOLVED 必须由独立 Verifier 持当前版本验证证据设置")
    await validate_verification_facts(session, task, permit[2], require_passed=True)


async def require_verification_outcome(
    session: AsyncSession,
    task: AITask,
    evidence_id: UUID,
) -> VerificationOutcome | None:
    if _permit.get() != (task.id, task.status_version, evidence_id):
        raise VerificationRequired("Runbook 计数只能由独立 Verifier 持当前证据更新")
    return await validate_verification_facts(session, task, evidence_id, require_passed=False)


async def validate_verification_facts(
    session: AsyncSession,
    task: AITask,
    evidence_id: UUID,
    *,
    require_passed: bool,
) -> VerificationOutcome | None:
    ledger = LedgerService(session)
    evidence = await ledger.get_evidence(evidence_id)
    if evidence.source_tool == "verify_chat":
        from app.verifier.chat import validate_chat_verification

        return await validate_chat_verification(
            session, task, evidence, require_passed=require_passed
        )
    if evidence.source_tool == "verify_war_room":
        from app.verifier.war_room import validate_war_room_verification

        return await validate_war_room_verification(
            session, task, evidence, require_passed=require_passed
        )
    if evidence.source_tool == "verify_architecture":
        from app.verifier.architecture import validate_architecture_verification

        return await validate_architecture_verification(
            session, task, evidence, require_passed=require_passed
        )
    if evidence.source_tool == "verify_inspection":
        from app.verifier.inspection import validate_inspection_verification

        return await validate_inspection_verification(
            session, task, evidence, require_passed=require_passed
        )
    if evidence.source_tool == "verify_release":
        from app.verifier.releases import validate_release_report

        return await validate_release_report(session, task, evidence, require_passed=require_passed)
    if evidence.source_tool in {"verify_ticket", "verify_ticket_permission"}:
        from app.verifier.tickets import validate_ticket_report

        if require_passed and evidence.source_tool != "verify_ticket":
            raise VerificationRequired("仅权限验证不能设置 RESOLVED，还必须验证工单回填关闭")
        return await validate_ticket_report(
            session,
            task,
            evidence,
            final=evidence.source_tool == "verify_ticket",
            require_passed=require_passed,
        )
    report = VerificationReport.model_validate_json(json.dumps(evidence.result_snapshot))
    if (
        evidence.task_id != task.id
        or evidence.source_tool != "verify_action"
        or report.spec.task_id != task.id
        or report.spec.verifying_version != task.status_version
        or (require_passed and not report.passed)
        or evidence.parameters != report.spec.model_dump(mode="json")
    ):
        raise VerificationRequired("恢复证据不属于当前任务和版本，或验证未通过")
    audits = await ledger.audits_for_task(task.id)
    if not any(
        a.event_type is AuditEventType.TOOL_CALL
        and a.operation == "verify_action"
        and a.actor == "verifier"
        and a.outcome == "succeeded"
        and a.evidence_id == evidence.id
        and a.details.get("mode") == "live"
        for a in audits
    ):
        raise VerificationRequired("缺少独立 Verifier 的成功调用审计")
    for check in report.checks:
        if check.evidence_id is None:
            return None
        fact = await ledger.get_evidence(check.evidence_id)
        expected_tool = {
            "deployment": "get_k8s_status",
            "pods": "get_service_runtime",
            "http_5xx_ratio": "query_metrics",
            "http_p99_ms": "query_metrics",
            "http_success_ratio": "query_metrics",
            "logs": "query_logs",
            "traces": "query_traces",
            "resources": "get_cloud_resources",
        }[check.name]
        parameters = fact.parameters
        if (
            fact.source_tool != expected_tool
            or parameters.get("service_name") != report.spec.service_name
            or fact.collected_at > evidence.collected_at
        ):
            raise VerificationRequired("验证事实 Tool、服务或采集时间不匹配")
        if check.name in {"deployment", "pods"}:
            if parameters.get("namespace") != report.spec.namespace:
                raise VerificationRequired("验证 Kubernetes 事实的命名空间不匹配")
        elif parameters.get("start") != report.spec.start.isoformat().replace(
            "+00:00", "Z"
        ) or parameters.get("end") != report.spec.end.isoformat().replace("+00:00", "Z"):
            raise VerificationRequired("验证事实窗口与报告不匹配")
        if check.name.startswith("http_") and parameters.get("metric_name") != check.name:
            raise VerificationRequired("验证指标事实与检查项不匹配")
        if fact.task_id != task.id or not any(
            a.event_type is AuditEventType.TOOL_CALL
            and a.actor == "verifier"
            and a.outcome == "succeeded"
            and a.evidence_id == fact.id
            and a.details.get("mode") == "live"
            for a in audits
        ):
            raise VerificationRequired("恢复报告必须引用同任务的独立事实查询证据")
    return report

"""纯计算的恢复标准；缺数据、错误作用域和任一异常都不能成为恢复结论。"""

from app.connectors.cloud.models import CloudResources
from app.tools.kubernetes import KubernetesStatus, ServiceRuntime
from app.tools.observability import LogsOutput, MetricsOutput, TracesOutput
from app.verifier.models import VerificationConfig, VerificationSpec


def deployment_healthy(spec: VerificationSpec, data: KubernetesStatus) -> bool:
    if (data.cluster_name, data.namespace) != (spec.cluster_name, spec.namespace):
        return False
    if len(data.deployments) != 1:
        return False
    item = data.deployments[0]
    status = item.status
    return (
        item.metadata.name == spec.deployment_name
        and item.metadata.namespace == spec.namespace
        and item.metadata.generation is not None
        and status.observed_generation == item.metadata.generation
        and item.spec.replicas == spec.expected_replicas
        and status.replicas
        == status.updated_replicas
        == status.ready_replicas
        == status.available_replicas
        == spec.expected_replicas
        and any(c.type == "Available" and c.status == "True" for c in status.conditions)
        and not any(c.status == "False" for c in status.conditions)
    )


def pods_healthy(spec: VerificationSpec, data: ServiceRuntime) -> bool:
    if (data.cluster_name, data.namespace, data.service_name) != (
        spec.cluster_name,
        spec.namespace,
        spec.service_name,
    ) or len(data.pods) != spec.expected_replicas:
        return False
    for pod in data.pods:
        if pod.metadata.namespace != spec.namespace or pod.status.phase != "Running":
            return False
        if not any(c.type == "Ready" and c.status == "True" for c in pod.status.conditions):
            return False
        by_name = {c.name: c for c in pod.status.container_statuses}
        if len(by_name) != len(pod.spec.containers) or not all(c.ready for c in by_name.values()):
            return False
        if set(by_name) != {c.name for c in pod.spec.containers}:
            return False
        targets = [c for c in pod.spec.containers if c.name == spec.container_name]
        if len(targets) != 1 or targets[0].image != spec.expected_image:
            return False
    return True


def metrics_healthy(
    spec: VerificationSpec, config: VerificationConfig, data: MetricsOutput, metric: str
) -> bool:
    if (data.service_name, data.start, data.end) != (spec.service_name, spec.start, spec.end):
        return False
    if not data.series:
        return False
    for series in data.series:
        if (series.service_name, series.metric_name) != (spec.service_name, metric):
            return False
        points = sorted(series.points, key=lambda p: p.timestamp)
        if len(points) < config.min_metric_points:
            return False
        timestamps = [p.timestamp for p in points]
        if len(set(timestamps)) != len(timestamps) or any(not spec.contains(t) for t in timestamps):
            return False
        if (
            (timestamps[0] - spec.start).total_seconds() > config.step_seconds
            or (spec.end - timestamps[-1]).total_seconds() > config.step_seconds
            or any(
                (b - a).total_seconds() > config.max_sample_gap_seconds
                for a, b in zip(timestamps, timestamps[1:], strict=False)
            )
        ):
            return False
        for point in points:
            if metric == "http_5xx_ratio" and not 0 <= point.value <= config.max_5xx_ratio:
                return False
            if metric == "http_p99_ms" and not 0 <= point.value <= config.max_p99_ms:
                return False
            if metric == "http_success_ratio" and not config.min_success_ratio <= point.value <= 1:
                return False
    return True


def logs_healthy(spec: VerificationSpec, data: LogsOutput) -> bool:
    return (data.service_name, data.start, data.end) == (
        spec.service_name,
        spec.start,
        spec.end,
    ) and all(
        item.service_name == spec.service_name
        and spec.contains(item.timestamp)
        and item.level.upper() in {"TRACE", "DEBUG", "INFO", "NOTICE", "WARN", "WARNING"}
        for item in data.logs
    )


def traces_healthy(spec: VerificationSpec, config: VerificationConfig, data: TracesOutput) -> bool:
    if (data.service_name, data.start, data.end) != (spec.service_name, spec.start, spec.end):
        return False
    if not data.traces:
        return False
    for trace in data.traces:
        if (
            trace.service_name != spec.service_name
            or not spec.contains(trace.timestamp)
            or trace.duration_ms > config.max_p99_ms
            or not trace.spans
            or not any(span.service_name == spec.service_name for span in trace.spans)
        ):
            return False
        for span in trace.spans:
            code = span.result_code
            if not spec.contains(span.timestamp) or not (
                code.lower() in {"ok", "success", "0"}
                or (code.isdigit() and 200 <= int(code) < 300)
            ):
                return False
    return True


def resources_healthy(
    spec: VerificationSpec, config: VerificationConfig, data: CloudResources
) -> bool:
    if (data.service_name, data.start, data.end) != (spec.service_name, spec.start, spec.end):
        return False
    by_id = {r.identity: r for r in data.resources}
    for target in spec.resources:
        resource = by_id.get((target.product, target.region_id, target.resource_id))
        if resource is None or resource.status != target.healthy_status:
            return False
        sample = resource.rds_connections
        if resource.product == "rds":
            if (
                sample is None
                or sample.availability != "available"
                or sample.sampled_at is None
                or not spec.contains(sample.sampled_at)
                or (spec.end - sample.sampled_at).total_seconds() > config.max_sample_gap_seconds
                or sample.max_connections is None
                or sample.max_connections <= 0
                or sample.total_connections is None
                or sample.total_connections / sample.max_connections
                > config.max_rds_connection_ratio
            ):
                return False
    targets = {(r.product, r.region_id, r.resource_id) for r in spec.resources}
    return not any(
        (e.product, e.region_id, e.resource_id) in targets and e.level in {"CRITICAL", "WARN"}
        for e in data.events
    )

"""宿主提供的验证目标和阈值；验证不使用 LLM 判断或执行任何动作。"""

import hashlib
import json
from dataclasses import dataclass
from datetime import UTC, datetime
from typing import Annotated
from uuid import UUID

from pydantic import AwareDatetime, Field, StringConstraints, field_validator, model_validator

from app.connectors.observability.models import Window
from app.tasks.workflow_models import TaskSnapshot
from app.tools.models import ToolModel

Text = Annotated[str, StringConstraints(strip_whitespace=True, min_length=1, max_length=512)]


class ResourceExpectation(ToolModel):
    product: Text
    region_id: Text
    resource_id: Text
    healthy_status: Text


class VerificationConfig(ToolModel):
    max_5xx_ratio: float = Field(default=0.01, ge=0, lt=1, allow_inf_nan=False)
    max_p99_ms: float = Field(default=500.0, gt=0, allow_inf_nan=False)
    min_success_ratio: float = Field(default=0.99, gt=0, le=1, allow_inf_nan=False)
    max_rds_connection_ratio: float = Field(default=0.8, gt=0, le=1, allow_inf_nan=False)
    step_seconds: int = Field(default=60, ge=1, le=3600)
    min_metric_points: int = Field(default=3, ge=2, le=1000)
    max_sample_gap_seconds: int = Field(default=120, ge=1, le=3600)
    window_seconds: int = Field(default=300, ge=60, le=86400)
    resources_by_service: dict[str, tuple[ResourceExpectation, ...]] = Field(default_factory=dict)

    @field_validator("resources_by_service", mode="before")
    @classmethod
    def resource_arrays(cls, value: object) -> object:
        # pydantic-settings 将环境 JSON 先解码为 Python；只规范数组容器，仍严格验证各字段。
        if isinstance(value, dict):
            return {
                key: tuple(items) if isinstance(items, list) else items
                for key, items in value.items()
            }
        return value

    @model_validator(mode="after")
    def gap(self) -> "VerificationConfig":
        if self.max_sample_gap_seconds < self.step_seconds:
            raise ValueError("验证允许的采样间隔不能小于查询采样间隔")
        if self.window_seconds < self.step_seconds * (self.min_metric_points - 1):
            raise ValueError("验证窗口必须覆盖最少采样点")
        return self


def criteria_hash(config: VerificationConfig) -> str:
    """证据只保存判定配置的指纹，绝不把环境变量配置对象写入数据库。"""
    canonical = json.dumps(config.model_dump(mode="json"), sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


class VerificationSpec(Window, ToolModel):
    task_id: UUID
    verifying_version: int = Field(ge=1)
    action_id: Text
    action_completed_at: AwareDatetime
    cluster_name: Text
    namespace: Text
    deployment_name: Text
    container_name: Text
    expected_image: Text
    expected_replicas: int = Field(ge=1, le=10000)
    resources: Annotated[tuple[ResourceExpectation, ...], Field(min_length=1, max_length=100)]

    @field_validator("action_completed_at")
    @classmethod
    def utc_action_time(cls, value: datetime) -> datetime:
        return value.astimezone(UTC)

    @model_validator(mode="after")
    def after_action(self) -> "VerificationSpec":
        if self.action_completed_at > self.start:
            raise ValueError("验证窗口必须在动作完成之后")
        identities = [(r.product, r.region_id, r.resource_id) for r in self.resources]
        if len(set(identities)) != len(identities):
            raise ValueError("验证资源目标不能重复")
        return self


class VerificationCheck(ToolModel):
    name: Text
    passed: bool
    reason: Text
    evidence_id: UUID | None = None


class VerificationReport(ToolModel):
    spec: VerificationSpec
    criteria_hash: Annotated[str, StringConstraints(pattern=r"^[0-9a-f]{64}$")]
    checks: Annotated[tuple[VerificationCheck, ...], Field(min_length=8, max_length=8)]

    @model_validator(mode="after")
    def complete_checks(self) -> "VerificationReport":
        if tuple(c.name for c in self.checks) != (
            "deployment",
            "pods",
            "http_5xx_ratio",
            "http_p99_ms",
            "http_success_ratio",
            "logs",
            "traces",
            "resources",
        ):
            raise ValueError("验证报告必须完整且按顺序包含八项独立检查")
        evidence_ids = [c.evidence_id for c in self.checks if c.evidence_id is not None]
        if len(evidence_ids) != len(set(evidence_ids)):
            raise ValueError("独立检查不能重复引用同一事实证据")
        return self

    @property
    def passed(self) -> bool:
        return all(check.passed and check.evidence_id is not None for check in self.checks)


@dataclass(frozen=True)
class VerificationRequest:
    task: TaskSnapshot
    spec_json: str


@dataclass(frozen=True)
class VerificationResult:
    task: TaskSnapshot
    evidence_id: str
    report_json: str

